    async function expandOidLoose({ fs, gitdir, oid: short }) {
        const prefix = short.slice(0, 2);
        const objectsSuffixes = await fs.readdir(`${gitdir}/objects/${prefix}`);
        return objectsSuffixes.map((suffix)=>`${prefix}${suffix}`).filter((_oid)=>_oid.startsWith(short));
    }
    async function expandOidPacked({ fs, cache, gitdir, oid: short, getExternalRefDelta }) {
        // Iterate through all the .pack files
        const results = [];
        let list = await fs.readdir(join(gitdir, 'objects/pack'));
        list = list.filter((x)=>x.endsWith('.idx'));
        for (const filename of list){
            const indexFile = `${gitdir}/objects/pack/${filename}`;
            const p = await readPackIndex({
                fs,
                cache,
                filename: indexFile,
                getExternalRefDelta
            });
            if (p.error) throw new InternalError(p.error);
            // Search through the list of oids in the packfile
            for (const oid of p.offsets.keys()){
                if (oid.startsWith(short)) results.push(oid);
            }
        }
        return results;
    }
    async function _expandOid({ fs, cache, gitdir, oid: short }) {
        // Curry the current read method so that the packfile un-deltification
        // process can acquire external ref-deltas.
        const getExternalRefDelta = (oid)=>_readObject({
                fs,
                cache,
                gitdir,
                oid
            });
        const results = await expandOidLoose({
            fs,
            gitdir,
            oid: short
        });
        const packedOids = await expandOidPacked({
            fs,
            cache,
            gitdir,
            oid: short,
            getExternalRefDelta
        });
        // Objects can exist in a pack file as well as loose, make sure we only get a list of unique oids.
        for (const packedOid of packedOids){
            if (results.indexOf(packedOid) === -1) {
                results.push(packedOid);
            }
        }
        if (results.length === 1) {
            return results[0];
        }
        if (results.length > 1) {
            throw new AmbiguousError('oids', short, results);
        }
        throw new NotFoundError(`an object matching "${short}"`);
    }
