            // Are any of the parents the sought-after ancestor?
            for (const parent of commit.parent){
                if (parent === ancestor) return true;
            }
            // If not, add them to heads (unless we know this is a shallow commit)
            if (!shallows.has(oid)) {
                for (const parent of commit.parent){
                    if (!visited.has(parent)) {
                        queue.push(parent);
                        visited.add(parent);
                    }
                }
            }
